<?php $area ??= []; $prefix ??= 'area'; $existingConditions = []; foreach (array_merge($vehicleDamage['current'], $vehicleDamage['history'] ?? [], $vehicleDamage['related'] ?? []) as $condition) { $existingConditions[(int) $condition['id']] = $condition; } ?>
