<label>Panel<select name="<?= esc($prefix, 'attr') ?>[panel_code]" required><option value="">Choose panel</option><?php foreach (\Config\VehicleDamage::PANELS as $code => $label): ?><option value="<?= esc($code, 'attr') ?>"<?= ($area['panel_code'] ?? '') === $code ? ' selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Damage type<select name="<?= esc($prefix, 'attr') ?>[damage_type_code]" required><?php foreach (\App\Services\Fleet\VehicleDamageService::DAMAGE_TYPES as $code => $label): ?><option value="<?= esc($code, 'attr') ?>"<?= ($area['damage_type_code'] ?? '') === $code ? ' selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Severity<select name="<?= esc($prefix, 'attr') ?>[severity_code]" required><?php foreach (\App\Services\Fleet\VehicleDamageService::SEVERITIES as $code => $label): ?><option value="<?= esc($code, 'attr') ?>"<?= ($area['severity_code'] ?? '') === $code ? ' selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
<label>Effect<select name="<?= esc($prefix, 'attr') ?>[effect_code]" required><?php foreach (\Config\VehicleDamage::EFFECTS as $code => $label): ?><option value="<?= esc($code, 'attr') ?>"<?= ($area['effect_code'] ?? '') === $code ? ' selected' : '' ?>><?= esc($label) ?></option><?php endforeach; ?></select></label>
